 void buildGestures(){gestures=new GestureDetector(this,new GestureDetector.SimpleOnGestureListener(){@Override public boolean onDown(MotionEvent e){showControls();return true;}@Override public boolean onSingleTapConfirmed(MotionEvent e){if(locked){showToolbar(true);return true;}if(playerView.isControllerFullyVisible()){playerView.hideController();showToolbar(false);}else{playerView.showController();showToolbar(true);scheduleHide();}return true;}@Override public boolean onDoubleTap(MotionEvent e){if(locked||player==null)return true;long delta=e.getX()<root.getWidth()/2f?-10000:10000;player.seekTo(Math.max(0,Math.min(player.getDuration()>0?player.getDuration():Long.MAX_VALUE,player.getCurrentPosition()+delta)));if(wpHost)emitPartyPlayback();showFeedback(delta<0?"۱۰ ثانیه عقب":"۱۰ ثانیه جلو");return true;}@Override public boolean onScroll(MotionEvent start,MotionEvent now,float dx,float dy){if(locked||Math.abs(dy)<Math.abs(dx)||root.getHeight()==0)return true;float fraction=-dy/root.getHeight();if(start.getX()<root.getWidth()/2f)adjustBrightness(fraction);else adjustVolume(fraction);return true;}});gestureLayer.setOnTouchListener((v,e)->gestures.onTouchEvent(e));}
