 void showControls(){if(!locked)showToolbar(true);scheduleHide();}void scheduleHide(){handler.removeCallbacks(hideChrome);handler.postDelayed(hideChrome,4300);}final Runnable hideChrome=()->{if(!locked&&!playerView.isControllerFullyVisible())showToolbar(false);};void showToolbar(boolean show){toolbar.setVisibility(show?View.VISIBLE:View.GONE);if(locked){toolbar.setVisibility(View.VISIBLE);for(int i=0;i<toolbar.getChildCount();i++)toolbar.getChildAt(i).setVisibility(toolbar.getChildAt(i)==lockButton?View.VISIBLE:View.GONE);}}
